{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js"
  }
}
import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { DatabaseSync } from 'node:sqlite';

const port = Number(process.env.PORT || 8080);
const dbPath = process.env.DB_PATH || './workboard.sqlite';
const db = new DatabaseSync(dbPath);
db.exec(`CREATE TABLE IF NOT EXISTS projects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
)`);
try { db.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0'); } catch (error) { if (!String(error.message).includes('duplicate column')) throw error; }
try { db.exec("ALTER TABLE projects ADD COLUMN default_priority TEXT NOT NULL DEFAULT 'Normal'"); } catch (error) { if (!String(error.message).includes('duplicate column')) throw error; }
db.exec(`CREATE TABLE IF NOT EXISTS tasks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
)`);
try { db.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal'"); } catch (error) { if (!String(error.message).includes('duplicate column')) throw error; }
try { db.exec('ALTER TABLE tasks ADD COLUMN due_date TEXT'); } catch (error) { if (!String(error.message).includes('duplicate column')) throw error; }
try { db.exec('ALTER TABLE tasks ADD COLUMN sort_order INTEGER'); } catch (error) { if (!String(error.message).includes('duplicate column')) throw error; }
db.exec('UPDATE tasks SET sort_order = id WHERE sort_order IS NULL');
// Keep each task's position in every project it has belonged to. The migration
// seeds the current ordering so introducing this feature does not reorder data.
db.exec(`CREATE TABLE IF NOT EXISTS task_project_positions (
  task_id INTEGER NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
  project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  position INTEGER NOT NULL,
  PRIMARY KEY (task_id, project_id),
  UNIQUE (project_id, position)
)`);
db.exec(`INSERT OR IGNORE INTO task_project_positions (task_id, project_id, position)
  SELECT id, project_id, sort_order FROM tasks`);

function canonicalDueDate(value) {
  const date = value.trim();
  if (!date) return { valid: true, value: null };
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(date);
  if (!match) return { valid: false };
  const year = Number(match[1]), month = Number(match[2]), day = Number(match[3]);
  if (year < 1 || month < 1 || month > 12) return { valid: false };
  const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
  const monthDays = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (day < 1 || day > monthDays[month - 1]) return { valid: false };
  return { valid: true, value: date };
}

const indexHtml = await readFile(new URL('./index.html', import.meta.url));
const projectHtml = await readFile(new URL('./project.html', import.meta.url));

function json(response, status, data) {
  response.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  response.end(JSON.stringify(data));
}

async function readBody(request) {
  let body = '';
  for await (const chunk of request) body += chunk;
  try { return JSON.parse(body); } catch { return null; }
}

const server = createServer(async (request, response) => {
  const url = new URL(request.url, `http://${request.headers.host || 'localhost'}`);
  if (request.method === 'GET' && url.pathname === '/health') {
    json(response, 200, { status: 'ok' });
    return;
  }
  if (request.method === 'GET' && url.pathname === '/api/projects') {
    const archived = url.searchParams.get('archived') === 'true' ? 1 : 0;
    json(response, 200, db.prepare(`SELECT p.id, p.name, p.archived,
      (SELECT COUNT(*) FROM tasks t WHERE t.project_id = p.id AND t.completed = 1) AS completed_count,
      (SELECT COUNT(*) FROM tasks t WHERE t.project_id = p.id) AS total_count
      FROM projects p WHERE p.archived = ? ORDER BY p.id`).all(archived).map(p => ({...p, archived: Boolean(p.archived)})));
    return;
  }
  if (request.method === 'POST' && url.pathname === '/api/projects') {
    const body = await readBody(request);
    const name = typeof body?.name === 'string' ? body.name.trim() : '';
    if (!name) { json(response, 400, { error: 'Project name is required' }); return; }
    const result = db.prepare('INSERT INTO projects (name) VALUES (?)').run(name);
    json(response, 201, { id: Number(result.lastInsertRowid), name });
    return;
  }
  const projectMatch = url.pathname.match(/^\/api\/projects\/(\d+)$/);
  if (request.method === 'GET' && projectMatch) {
    const project = db.prepare('SELECT id, name, archived, default_priority FROM projects WHERE id = ?').get(Number(projectMatch[1]));
    if (!project) { json(response, 404, { error: 'Project not found' }); return; }
    json(response, 200, {...project, archived: Boolean(project.archived)});
    return;
  }
  if (request.method === 'PATCH' && projectMatch) {
    const projectId = Number(projectMatch[1]);
    const project = db.prepare('SELECT archived FROM projects WHERE id = ?').get(projectId);
    if (!project) { json(response, 404, { error: 'Project not found' }); return; }
    if (project.archived) { json(response, 403, { error: 'Archived project' }); return; }
    const body = await readBody(request);
    if (Object.hasOwn(body || {}, 'default_priority')) {
      const priority = body.default_priority;
      if (!['Low', 'Normal', 'High'].includes(priority)) { json(response, 400, { error: 'Invalid default task priority' }); return; }
      db.prepare('UPDATE projects SET default_priority = ? WHERE id = ?').run(priority, projectId);
      json(response, 200, { id: projectId, default_priority: priority });
      return;
    }
    const name = typeof body?.name === 'string' ? body.name.trim() : '';
    if (!name) { json(response, 400, { error: 'Project name is required' }); return; }
    db.prepare('UPDATE projects SET name = ? WHERE id = ?').run(name, projectId);
    json(response, 200, { id: projectId, name });
    return;
  }
  const archiveMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/(archive|restore)$/);
  if (request.method === 'POST' && archiveMatch) {
    const result = db.prepare('UPDATE projects SET archived = ? WHERE id = ?').run(archiveMatch[2] === 'archive' ? 1 : 0, Number(archiveMatch[1]));
    if (!result.changes) { json(response, 404, { error: 'Project not found' }); return; }
    json(response, 200, { archived: archiveMatch[2] === 'archive' });
    return;
  }
  const tasksMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks$/);
  if (tasksMatch && request.method === 'GET') {
    const projectId = Number(tasksMatch[1]);
    const project = db.prepare('SELECT id FROM projects WHERE id = ?').get(projectId);
    if (!project) { json(response, 404, { error: 'Project not found' }); return; }
    json(response, 200, db.prepare('SELECT id, title, completed, priority, due_date FROM tasks WHERE project_id = ? ORDER BY sort_order, id').all(projectId).map(task => ({ ...task, completed: Boolean(task.completed) })));
    return;
  }
  const moveMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks\/(\d+)\/move$/);
  if (moveMatch && request.method === 'POST') {
    const sourceId = Number(moveMatch[1]), taskId = Number(moveMatch[2]);
    const body = await readBody(request);
    const destinationId = Number(body?.destination_project_id);
    const source = db.prepare('SELECT archived FROM projects WHERE id = ?').get(sourceId);
    const destination = db.prepare('SELECT archived FROM projects WHERE id = ?').get(destinationId);
    if (!source || !destination) { json(response, 404, { error: 'Project not found' }); return; }
    if (source.archived || destination.archived) { json(response, 403, { error: 'Archived projects cannot move tasks' }); return; }
    const task = db.prepare('SELECT id FROM tasks WHERE id = ? AND project_id = ?').get(taskId, sourceId);
    if (!task) { json(response, 404, { error: 'Task not found' }); return; }
    let destinationPosition = db.prepare('SELECT position FROM task_project_positions WHERE task_id = ? AND project_id = ?').get(taskId, destinationId)?.position;
    if (destinationPosition === undefined) {
      destinationPosition = db.prepare('SELECT COALESCE(MAX(position), 0) + 1 AS value FROM task_project_positions WHERE project_id = ?').get(destinationId).value;
      db.prepare('INSERT INTO task_project_positions (task_id, project_id, position) VALUES (?, ?, ?)').run(taskId, destinationId, destinationPosition);
    }
    db.prepare('UPDATE tasks SET project_id = ?, sort_order = ? WHERE id = ? AND project_id = ?').run(destinationId, destinationPosition, taskId, sourceId);
    json(response, 200, { id: taskId, project_id: destinationId });
    return;
  }
  if (tasksMatch && request.method === 'POST') {
    const projectId = Number(tasksMatch[1]);
    if (!db.prepare('SELECT id FROM projects WHERE id = ?').get(projectId)) { json(response, 404, { error: 'Project not found' }); return; }
    if (db.prepare('SELECT archived FROM projects WHERE id = ?').get(projectId).archived) { json(response, 403, { error: 'Archived project' }); return; }
    const body = await readBody(request);
    const title = typeof body?.title === 'string' ? body.title.trim() : '';
    if (!title) { json(response, 400, { error: 'Task title is required' }); return; }
    const defaultPriority = db.prepare('SELECT default_priority FROM projects WHERE id = ?').get(projectId).default_priority;
    const nextOrder = db.prepare('SELECT COALESCE(MAX(sort_order), 0) + 1 AS value FROM tasks WHERE project_id = ?').get(projectId).value;
    const result = db.prepare('INSERT INTO tasks (project_id, title, priority, sort_order) VALUES (?, ?, ?, ?)').run(projectId, title, defaultPriority, nextOrder);
    db.prepare('INSERT INTO task_project_positions (task_id, project_id, position) VALUES (?, ?, ?)').run(Number(result.lastInsertRowid), projectId, nextOrder);
    json(response, 201, { id: Number(result.lastInsertRowid), title, completed: false, priority: defaultPriority });
    return;
  }
  const taskMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks\/(\d+)$/);
  if (taskMatch && request.method === 'PATCH') {
    const projectId = Number(taskMatch[1]);
    const taskId = Number(taskMatch[2]);
    const body = await readBody(request);
    if (db.prepare('SELECT archived FROM projects WHERE id = ?').get(projectId)?.archived) { json(response, 403, { error: 'Archived project' }); return; }
    if (Object.hasOwn(body || {}, 'title')) {
      const title = typeof body.title === 'string' ? body.title.trim() : '';
      if (!title) { json(response, 400, { error: 'Task title is required' }); return; }
      const result = db.prepare('UPDATE tasks SET title = ? WHERE id = ? AND project_id = ?').run(title, taskId, projectId);
      if (!result.changes) { json(response, 404, { error: 'Task not found' }); return; }
      json(response, 200, { id: taskId, title });
      return;
    }
    if (Object.hasOwn(body || {}, 'priority')) {
      const priority = body.priority;
      if (!['Low', 'Normal', 'High'].includes(priority)) { json(response, 400, { error: 'Invalid task priority' }); return; }
      const result = db.prepare('UPDATE tasks SET priority = ? WHERE id = ? AND project_id = ?').run(priority, taskId, projectId);
      if (!result.changes) { json(response, 404, { error: 'Task not found' }); return; }
      json(response, 200, { id: taskId, priority });
      return;
    }
    if (Object.hasOwn(body || {}, 'due_date')) {
      if (typeof body.due_date !== 'string') { json(response, 400, { error: 'Due date must be a valid YYYY-MM-DD date' }); return; }
      const dueDate = canonicalDueDate(body.due_date);
      if (!dueDate.valid) { json(response, 400, { error: 'Due date must be a valid YYYY-MM-DD date' }); return; }
      const result = db.prepare('UPDATE tasks SET due_date = ? WHERE id = ? AND project_id = ?').run(dueDate.value, taskId, projectId);
      if (!result.changes) { json(response, 404, { error: 'Task not found' }); return; }
      json(response, 200, { id: taskId, due_date: dueDate.value });
      return;
    }
    if (typeof body?.completed !== 'boolean') { json(response, 400, { error: 'Completion state is required' }); return; }
    const result = db.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?').run(body.completed ? 1 : 0, taskId, projectId);
    if (!result.changes) { json(response, 404, { error: 'Task not found' }); return; }
    json(response, 200, { id: taskId, completed: body.completed });
    return;
  }
  if (request.method === 'GET' && url.pathname === '/') {
    response.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    response.end(indexHtml);
    return;
  }
  if (request.method === 'GET' && /^\/projects\/\d+$/.test(url.pathname)) {
    response.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    response.end(projectHtml);
    return;
  }
  response.writeHead(404, { 'content-type': 'text/plain; charset=utf-8' });
  response.end('Not found');
});

server.listen(port, '0.0.0.0');
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Project · Workboard</title>
  <style>
    body { max-width: 48rem; margin: 3rem auto; padding: 0 1rem; font: 16px/1.5 system-ui, sans-serif; color: #172033; }
    button { font: inherit; padding: .55rem .75rem; cursor: pointer; }
    form { display: flex; gap: .6rem; align-items: end; flex-wrap: wrap; margin-top: 1rem; }
    label { display: grid; gap: .25rem; }
    input, select { font: inherit; padding: .55rem .75rem; }
    #alert { color: #a12622; min-height: 1.5em; }
    #tasks { list-style: none; padding: 0; }
    .task-row { border-top: 1px solid #d8deea; padding: .85rem 0; display: flex; align-items: center; gap: .65rem; }
    .task-row input[type="text"] { min-width: 8rem; }
    .due-date-form { display: flex; gap: .35rem; align-items: center; margin: 0; }
    .task-row select { font: inherit; padding: .55rem .75rem; }
  </style>
</head>
<body>
  <main>
    <button id="back" type="button">Projects</button>
    <h1 id="project-name"></h1>
    <p id="archived-banner" hidden>Archived project</p>
    <p id="missing" role="alert" hidden>Project not found</p>
    <form id="rename-form" hidden>
      <label>New project name<input id="new-project-name" name="name" type="text" autocomplete="off"></label>
      <button type="submit">Rename project</button>
    </form>
    <section id="task-section" hidden aria-label="Tasks">
      <form id="create-form">
        <label>Task title<input id="task-title" name="title" type="text" autocomplete="off"></label>
        <button type="submit">Create task</button>
      </form>
      <p id="alert" role="alert" aria-live="polite"></p>
      <label>Task filter<select id="task-filter"><option>All</option><option>Open</option><option>Completed</option></select></label>
      <label>Priority filter<select id="priority-filter"><option>All</option><option>Low</option><option>Normal</option><option>High</option></select></label>
      <label>Default task priority<select id="default-priority"><option>Low</option><option>Normal</option><option>High</option></select></label>
      <div id="due-range">
        <label>Due from<input id="due-from" type="text" autocomplete="off"></label>
        <label>Due through<input id="due-through" type="text" autocomplete="off"></label>
        <button id="apply-due-range" type="button">Apply due range</button>
      </div>
      <ul id="tasks" aria-label="Tasks"></ul>
    </section>
  </main>
  <script type="module">
    document.querySelector('#back').addEventListener('click', () => { window.location.href = '/'; });
    const id = window.location.pathname.split('/').pop();
    const response = await fetch(`/api/projects/${encodeURIComponent(id)}`);
    if (response.ok) {
      const project = await response.json();
      document.querySelector('#project-name').textContent = project.name;
      const renameForm = document.querySelector('#rename-form');
      renameForm.hidden = false;
      if (project.archived) {
        document.querySelector('#archived-banner').hidden = false;
        document.querySelector('#create-form button').disabled = true;
        renameForm.querySelector('input').disabled = true;
        renameForm.querySelector('button').disabled = true;
      }
      const defaultPriority = document.querySelector('#default-priority');
      defaultPriority.value = project.default_priority || 'Normal';
      defaultPriority.disabled = project.archived;
      defaultPriority.addEventListener('change', async () => {
        const updateResponse = await fetch(`/api/projects/${encodeURIComponent(id)}`, {
          method: 'PATCH',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify({ default_priority: defaultPriority.value })
        });
        if (!updateResponse.ok) {
          const error = await updateResponse.json();
          document.querySelector('#alert').textContent = error.error || 'Unable to update default task priority';
        } else {
          project.default_priority = defaultPriority.value;
        }
      });
      document.title = `${project.name} · Workboard`;
      document.querySelector('#task-section').hidden = false;
      renameForm.addEventListener('submit', async event => {
        event.preventDefault();
        const alertBox = document.querySelector('#alert');
        alertBox.textContent = '';
        const name = document.querySelector('#new-project-name').value.trim();
        if (!name) { alertBox.textContent = 'Project name is required'; return; }
        const renameResponse = await fetch(`/api/projects/${encodeURIComponent(id)}`, {
          method: 'PATCH',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify({ name })
        });
        if (!renameResponse.ok) {
          const error = await renameResponse.json();
          alertBox.textContent = error.error || 'Unable to rename project';
          return;
        }
        project.name = name;
        document.querySelector('#project-name').textContent = name;
        document.title = `${name} · Workboard`;
        document.querySelector('#new-project-name').value = '';
      });
      const taskList = document.querySelector('#tasks');
      const filter = document.querySelector('#task-filter');
      const priorityFilter = document.querySelector('#priority-filter');
      let appliedDueRange = { from: '', through: '' };
      function validCalendarDate(value) {
        const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
        if (!match) return false;
        const year = Number(match[1]), month = Number(match[2]), day = Number(match[3]);
        if (year < 1 || month < 1 || month > 12) return false;
        const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
        return day >= 1 && day <= [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month - 1];
      }
      document.querySelector('#apply-due-range').addEventListener('click', async () => {
        const alertBox = document.querySelector('#alert');
        alertBox.textContent = '';
        const from = document.querySelector('#due-from').value.trim();
        const through = document.querySelector('#due-through').value.trim();
        if ((from && !validCalendarDate(from)) || (through && !validCalendarDate(through))) {
          alertBox.textContent = 'Due range must use valid YYYY-MM-DD dates';
          return;
        }
        if (from && through && from > through) {
          alertBox.textContent = 'Due from must not be after Due through';
          return;
        }
        appliedDueRange = { from, through };
        await loadTasks();
      });
      async function loadTasks() {
        const taskResponse = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks`);
        const tasks = await taskResponse.json();
        const destinationResponse = await fetch('/api/projects?archived=false');
        const destinations = (await destinationResponse.json()).filter(item => String(item.id) !== String(id));
        const visible = tasks.filter(task =>
          (filter.value === 'All' || (filter.value === 'Open' ? !task.completed : task.completed)) &&
          (priorityFilter.value === 'All' || task.priority === priorityFilter.value) &&
          ((!appliedDueRange.from && !appliedDueRange.through) || (!!task.due_date &&
            (!appliedDueRange.from || task.due_date >= appliedDueRange.from) &&
            (!appliedDueRange.through || task.due_date <= appliedDueRange.through)))
        );
        taskList.replaceChildren(...visible.map(task => {
          const row = document.createElement('li');
          row.dataset.testid = 'task-row';
          row.className = 'task-row';
          const checkbox = document.createElement('input');
          checkbox.type = 'checkbox';
          checkbox.checked = task.completed;
          checkbox.disabled = project.archived;
          checkbox.setAttribute('aria-label', `Complete ${task.title}`);
          checkbox.addEventListener('change', async () => {
            await fetch(`/api/projects/${encodeURIComponent(id)}/tasks/${task.id}`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ completed: checkbox.checked }) });
            await loadTasks();
          });
          const title = document.createElement('span');
          title.textContent = task.title;
          const renameInput = document.createElement('input');
          renameInput.type = 'text';
          renameInput.setAttribute('aria-label', 'New task title');
          renameInput.value = task.title;
          renameInput.disabled = project.archived;
          const renameButton = document.createElement('button');
          renameButton.type = 'button';
          renameButton.textContent = 'Rename task';
          renameButton.disabled = project.archived;
          renameButton.addEventListener('click', async () => {
            const alertBox = document.querySelector('#alert');
            alertBox.textContent = '';
            const newTitle = renameInput.value.trim();
            if (!newTitle) { alertBox.textContent = 'Task title is required'; return; }
            const renameResponse = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks/${task.id}`, {
              method: 'PATCH',
              headers: { 'content-type': 'application/json' },
              body: JSON.stringify({ title: newTitle })
            });
            if (!renameResponse.ok) {
              const error = await renameResponse.json();
              alertBox.textContent = error.error || 'Unable to rename task';
              return;
            }
            await loadTasks();
          });
          const priority = document.createElement('select');
          priority.setAttribute('aria-label', 'Task priority');
          for (const value of ['Low', 'Normal', 'High']) {
            const option = document.createElement('option');
            option.value = value;
            option.textContent = value;
            priority.append(option);
          }
          priority.value = task.priority || 'Normal';
          priority.disabled = project.archived;
          priority.addEventListener('change', async () => {
            const priorityResponse = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks/${task.id}`, {
              method: 'PATCH',
              headers: { 'content-type': 'application/json' },
              body: JSON.stringify({ priority: priority.value })
            });
            if (!priorityResponse.ok) {
              const error = await priorityResponse.json();
              document.querySelector('#alert').textContent = error.error || 'Unable to update priority';
            } else {
              await loadTasks();
            }
          });
          const dueDateForm = document.createElement('form');
          dueDateForm.className = 'due-date-form';
          const dueDateLabel = document.createElement('label');
          dueDateLabel.textContent = 'Task due date';
          const dueDateInput = document.createElement('input');
          dueDateInput.type = 'text';
          dueDateInput.setAttribute('aria-label', 'Task due date');
          dueDateInput.value = task.due_date || '';
          dueDateInput.disabled = project.archived;
          dueDateLabel.append(dueDateInput);
          const saveDueDate = document.createElement('button');
          saveDueDate.type = 'submit';
          saveDueDate.textContent = 'Save due date';
          saveDueDate.disabled = project.archived;
          dueDateForm.append(dueDateLabel, saveDueDate);
          dueDateForm.addEventListener('submit', async event => {
            event.preventDefault();
            const alertBox = document.querySelector('#alert');
            alertBox.textContent = '';
            const dateResponse = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks/${task.id}`, {
              method: 'PATCH',
              headers: { 'content-type': 'application/json' },
              body: JSON.stringify({ due_date: dueDateInput.value })
            });
            if (!dateResponse.ok) {
              const error = await dateResponse.json();
              alertBox.textContent = error.error || 'Unable to save due date';
              return;
            }
            await loadTasks();
          });
          const destination = document.createElement('select');
          destination.setAttribute('aria-label', 'Destination project');
          for (const item of destinations) {
            const option = document.createElement('option');
            option.value = item.id;
            option.textContent = item.name;
            destination.append(option);
          }
          const moveButton = document.createElement('button');
          moveButton.type = 'button';
          moveButton.textContent = 'Move task';
          destination.disabled = project.archived || destinations.length === 0;
          moveButton.disabled = destination.disabled;
          moveButton.addEventListener('click', async () => {
            const moveResponse = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks/${task.id}/move`, {
              method: 'POST', headers: { 'content-type': 'application/json' },
              body: JSON.stringify({ destination_project_id: Number(destination.value) })
            });
            if (!moveResponse.ok) {
